import math

def _safe_num(val, default=0.0) -> float:
    if val is None:
        return default
    try:
        f = float(val)
        return default if math.isnan(f) else f
    except (ValueError, TypeError):
        return default

def predict_biopsy(row: dict) -> tuple[str, float]:
    """Predict prostate biopsy decision ('yes' or 'no') and positive probability.
    Args:
        row: Dict of clinical patient features.
    Returns:
        Tuple of (decision: 'yes'|'no', probability_yes: float)
    """
    if _safe_num(row.get('radiology_report__pirads')) <= 3.0:
        if str(row.get('structured_prompt__bx', '')).strip().lower() == 'positive':
            return 'no', 0.3333
        else:
            return 'no', 0.0000
    else:
        if str(row.get('structured_prompt__bx', '')).strip().lower() == 'positive':
            if _safe_num(row.get('laboratory_results__psa')) > 10.0:
                return 'no', 0.4000
            else:
                if _safe_num(row.get('radiology_report__psa_density')) >= 0.2:
                    return 'yes', 0.6667
                else:
                    if _safe_num(row.get('radiology_report__psa_density')) >= 0.15:
                        return 'yes', 0.5000
                    else:
                        if _safe_num(row.get('structured_prompt__age')) > 65.0:
                            return 'no', 0.3333
                        else:
                            return 'yes', 0.5000
        else:
            if _safe_num(row.get('radiology_report__psa_density')) >= 0.2:
                return 'yes', 1.0000
            else:
                if _safe_num(row.get('structured_prompt__age')) <= 60.0:
                    return 'yes', 0.6667
                else:
                    return 'yes', 1.0000
